  const zF = T.cz + T.d / 2, zB = T.cz - T.d / 2, kB = (zB - VP.z) / (zF - VP.z);
  const F = (u: number, v: number) => new THREE.Vector3(T.cx - T.w / 2 + T.w * u, T.y0 + T.h * v, zF);
